/**
 * Newton's Second Law simulation for the Physics Lab.
 *
 * Deterministic core:  a = F / m   (idealized: constant net force, no friction
 * or air resistance).  The acceleration is ALWAYS computed here in code -- never
 * fetched from a server and never generated by AI.  This file mirrors the Python
 * reference model in apps/physics/simulations.py.
 */
(function (window, document) {
  "use strict";

  var PhysicsLab = window.PhysicsLab;
  if (!PhysicsLab) {
    if (window.console) window.console.warn("PhysicsLab shell not loaded.");
    return;
  }

  // --- deterministic core (kept in sync with simulations.py) -----------------

  var MIN_MASS_KG = 0.1;
  var MAX_MASS_KG = 20.0;
  var MIN_FORCE_N = 0.0;
  var MAX_FORCE_N = 50.0;

  function clampMass(massKg) {
    var mass = Number(massKg);
    if (!isFinite(mass) || mass <= 0) return NaN; // zero / negative rejected
    return Math.max(MIN_MASS_KG, Math.min(MAX_MASS_KG, mass));
  }

  function clampForce(forceN) {
    var force = Number(forceN);
    if (!isFinite(force)) return NaN;
    return Math.max(MIN_FORCE_N, Math.min(MAX_FORCE_N, force));
  }

  function computeAcceleration(sample) {
    var mass = clampMass(sample && sample.massKg);
    var force = clampForce(sample && sample.forceN);
    if (!isFinite(mass) || !isFinite(force)) return NaN;
    return force / mass; // a = F / m
  }

  // --- geometry constants for the SVG scene --------------------------------

  var TRACK_LEFT_PX = 70;
  var PX_PER_M = 25;
  var MAX_TRACK_M = 16;
  var REDUCED_MOTION_STOP_S = 6;

  // --- simulation factory -------------------------------------------------

  function createNewtonsSecondLawSim(root, config, lab) {
    var initial = {
      massKg: clampMass(config.mass) || 1,
      forceN: isFinite(clampForce(config.force)) ? clampForce(config.force) : 0
    };

    var state = {
      massKg: initial.massKg,
      forceN: initial.forceN,
      timeS: 0,
      velocityMs: 0,
      positionM: 0
    };
    var trace = [[0, 0]];
    var maxV = 1;
    var prediction = null;

    var $ = function (sel) {
      return root.querySelector(sel);
    };

    var el = {
      scene: $("[data-lab-scene]"),
      sceneDesc: $("[data-scene-desc]"),
      sceneStatus: $("[data-scene-status]"),
      cart: $("[data-cart]"),
      forceLine: $("[data-force-line]"),
      forceHead: $("[data-force-head]"),
      forceLabel: $("[data-force-label]"),
      accelLine: $("[data-accel-line]"),
      accelHead: $("[data-accel-head]"),
      accelLabel: $("[data-accel-label]"),
      graph: $("[data-lab-graph]"),
      trace: $("[data-lab-trace]"),
      valueMass: $("[data-value-mass]"),
      valueForce: $("[data-value-force]"),
      valueAccel: $("[data-value-accel]"),
      valueTime: $("[data-value-time]"),
      valueVelocity: $("[data-value-velocity]"),
      valuePosition: $("[data-value-position]"),
      eqAccel: $("[data-eq-accel]"),
      eqForce: $("[data-eq-force]"),
      eqMass: $("[data-eq-mass]"),
      inputMass: $("[data-input-mass]"),
      inputForce: $("[data-input-force]"),
      outMass: $("[data-out-mass]"),
      outForce: $("[data-out-force]"),
      start: $("[data-action-start]"),
      pause: $("[data-action-pause]"),
      reset: $("[data-action-reset]"),
      motionNote: $("[data-motion-note]"),
      predictionInput: $("[data-prediction-input]"),
      predictionSubmit: $("[data-prediction-submit]"),
      predictionTest: $("[data-prediction-test]"),
      predictionResult: $("[data-prediction-result]"),
      observation: $("[data-observation]"),
      tutorLink: $("[data-tutor-link]")
    };

    var loop = lab.createRunLoop(tick, { maxDt: 0.05, coarseDt: 0.2 });

    // -- integration ----------------------------------------------------

    function acceleration() {
      return computeAcceleration({ forceN: state.forceN, massKg: state.massKg });
    }

    function tick(dt) {
      var a = acceleration();
      state.velocityMs += a * dt;
      state.positionM += state.velocityMs * dt;
      state.timeS += dt;
      trace.push([state.timeS, state.velocityMs]);
      if (state.velocityMs > maxV) maxV = state.velocityMs;

      if (state.positionM >= MAX_TRACK_M) {
        state.positionM = MAX_TRACK_M;
        loop.stop();
        setStatus("The cart reached the end of the track. Press Reset to run again.");
      } else if (loop.reduced && state.timeS >= REDUCED_MOTION_STOP_S) {
        loop.stop();
        setStatus("Stepped through " + REDUCED_MOTION_STOP_S + " s. Press Reset to run again.");
      }
      render();
    }

    // -- public control surface --------------------------------------

    function setMass(value) {
      var mass = clampMass(value);
      if (isFinite(mass)) state.massKg = mass;
      syncInputs();
      render();
      return state.massKg;
    }

    function setForce(value) {
      var force = clampForce(value);
      if (isFinite(force)) state.forceN = force;
      syncInputs();
      render();
      return state.forceN;
    }

    function start() {
      if (state.positionM >= MAX_TRACK_M) return;
      loop.start();
      setStatus("Running. Time is advancing.");
    }

    function pause() {
      loop.stop();
      setStatus("Paused at t = " + state.timeS.toFixed(2) + " s.");
    }

    function reset() {
      loop.stop();
      state.timeS = 0;
      state.velocityMs = 0;
      state.positionM = 0;
      trace = [[0, 0]];
      maxV = 1;
      setStatus("Reset to the start. Mass and force are unchanged.");
      render();
    }

    function getState() {
      return {
        massKg: state.massKg,
        forceN: state.forceN,
        accelerationMs2: acceleration(),
        timeS: state.timeS,
        velocityMs: state.velocityMs,
        positionM: state.positionM,
        running: loop.isRunning()
      };
    }

    // -- rendering ---------------------------------------------------

    function setStatus(text) {
      if (el.sceneStatus) el.sceneStatus.textContent = text;
    }

    function syncInputs() {
      if (el.inputMass) el.inputMass.value = String(state.massKg);
      if (el.inputForce) el.inputForce.value = String(state.forceN);
      if (el.outMass) el.outMass.textContent = state.massKg.toFixed(1);
      if (el.outForce) el.outForce.textContent = state.forceN.toFixed(1);
    }

    function setText(node, text) {
      if (node) node.textContent = text;
    }

    function render() {
      var a = acceleration();
      var massText = state.massKg.toFixed(1);
      var forceText = state.forceN.toFixed(1);
      var accelText = a.toFixed(2);

      setText(el.valueMass, massText);
      setText(el.valueForce, forceText);
      setText(el.valueAccel, accelText);
      setText(el.valueTime, state.timeS.toFixed(2));
      setText(el.valueVelocity, state.velocityMs.toFixed(2));
      setText(el.valuePosition, state.positionM.toFixed(2));
      setText(el.eqAccel, accelText);
      setText(el.eqForce, forceText);
      setText(el.eqMass, massText);
      if (el.outMass) el.outMass.textContent = massText;
      if (el.outForce) el.outForce.textContent = forceText;

      renderScene(a);
      renderGraph();
      refreshTutorLink();
    }

    function renderScene(a) {
      var cartX = TRACK_LEFT_PX + state.positionM * PX_PER_M;
      if (el.cart) el.cart.setAttribute("transform", "translate(" + cartX + ",156)");

      var originX = cartX + 92;
      var forceLen = state.forceN <= 0 ? 0 : 18 + (state.forceN / MAX_FORCE_N) * 200;
      drawArrow(el.forceLine, el.forceHead, el.forceLabel, originX, 176, forceLen,
        "F = " + state.forceN.toFixed(1) + " N", state.forceN > 0);

      var accelLen = a <= 0 ? 0 : Math.min(220, 8 + a * 9);
      drawArrow(el.accelLine, el.accelHead, el.accelLabel, originX, 238, accelLen,
        "a = " + a.toFixed(2) + " m/s²", a > 0);

      var summary =
        "Mass " + state.massKg.toFixed(1) + " kilograms, net force " +
        state.forceN.toFixed(1) + " newtons, acceleration " + a.toFixed(2) +
        " metres per second squared. The cart has moved " +
        state.positionM.toFixed(2) + " metres in " + state.timeS.toFixed(2) + " seconds.";
      if (el.scene) el.scene.setAttribute("aria-label", summary);
      if (el.sceneDesc) el.sceneDesc.textContent = summary;
    }

    function drawArrow(line, head, label, x, y, length, text, visible) {
      if (!line || !head) return;
      var endX = x + length;
      line.setAttribute("x1", x);
      line.setAttribute("y1", y);
      line.setAttribute("x2", endX);
      line.setAttribute("y2", y);
      if (length < 1) {
        head.setAttribute("points", "0,0 0,0 0,0");
      } else {
        head.setAttribute(
          "points",
          endX + "," + (y - 6) + " " + (endX + 12) + "," + y + " " + endX + "," + (y + 6)
        );
      }
      if (label) {
        label.setAttribute("x", x + 4);
        label.setAttribute("y", y - 10);
        label.textContent = text;
      }
      var group = line.parentNode;
      if (group && group.setAttribute) {
        group.setAttribute("opacity", visible ? "1" : "0.35");
      }
    }

    function renderGraph() {
      if (!el.trace) return;
      var x0 = 40, x1 = 348, y0 = 156, y1 = 12;
      var tMax = Math.max(6, state.timeS);
      var vMax = Math.max(1, maxV * 1.15);
      var points = [];
      for (var i = 0; i < trace.length; i++) {
        var t = trace[i][0];
        var v = trace[i][1];
        var px = x0 + (t / tMax) * (x1 - x0);
        var py = y0 - (v / vMax) * (y0 - y1);
        points.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      el.trace.setAttribute("points", points.join(" "));
      if (el.graph) {
        el.graph.setAttribute(
          "aria-label",
          "Velocity reaches " + state.velocityMs.toFixed(2) + " metres per second after " +
            state.timeS.toFixed(2) + " seconds. A steeper line means a larger acceleration."
        );
      }
    }

    // -- prediction ------------------------------------------------

    var PREDICTION_LABELS = {
      double: "It doubles",
      half: "It is halved",
      same: "It stays the same",
      quadruple: "It quadruples"
    };
    var STORAGE_KEY = "physicslab:newtons_second_law:prediction";

    function loadStoredPrediction() {
      try {
        var stored = window.localStorage.getItem(STORAGE_KEY);
        if (stored && el.predictionInput && PREDICTION_LABELS[stored]) {
          el.predictionInput.value = stored;
        }
      } catch (err) {
        /* storage unavailable: prediction stays in-memory only */
      }
    }

    function submitPrediction() {
      if (!el.predictionInput) return;
      var choice = el.predictionInput.value;
      if (!choice) {
        setText(el.predictionResult, "Choose a prediction first.");
        return;
      }
      prediction = {
        choice: choice,
        baselineForce: state.forceN,
        baselineAccel: acceleration()
      };
      try {
        window.localStorage.setItem(STORAGE_KEY, choice);
      } catch (err) {
        /* ignore */
      }
      setText(
        el.predictionResult,
        "Prediction locked in: “" + PREDICTION_LABELS[choice] +
          "”. Now run the check."
      );
      if (el.predictionTest) el.predictionTest.hidden = false;
    }

    function testPrediction() {
      if (!prediction) {
        setText(el.predictionResult, "Make a prediction first.");
        return;
      }
      var targetForce = prediction.baselineForce * 2;
      var cappedNote = "";
      if (targetForce > MAX_FORCE_N) {
        targetForce = MAX_FORCE_N;
        cappedNote = " (force is capped at " + MAX_FORCE_N + " N, so it could not fully double)";
      }
      setForce(targetForce);
      var newAccel = acceleration();
      var ratio = prediction.baselineAccel > 0 ? newAccel / prediction.baselineAccel : 0;

      var actual;
      if (ratio >= 1.8 && ratio <= 2.2) actual = "double";
      else if (ratio >= 3.6) actual = "quadruple";
      else if (ratio > 0.4 && ratio < 0.6) actual = "half";
      else if (ratio >= 0.9 && ratio <= 1.1) actual = "same";
      else actual = "change by about " + ratio.toFixed(2) + "x";

      var correct = actual === prediction.choice;
      var verdict = correct
        ? "That matches your prediction."
        : "That is different from your prediction — look at a = F / m again.";
      setText(
        el.predictionResult,
        "Force went from " + prediction.baselineForce.toFixed(1) + " N to " +
          targetForce.toFixed(1) + " N" + cappedNote + ". Acceleration went from " +
          prediction.baselineAccel.toFixed(2) + " to " + newAccel.toFixed(2) +
          " m/s² — it " + (actual === "double" ? "doubled" :
            actual === "half" ? "halved" : actual === "same" ? "stayed the same" :
            actual === "quadruple" ? "quadrupled" : actual) + ". " + verdict
      );
    }

    // -- tutor connection --------------------------------------------

    function buildContext() {
      var a = acceleration();
      var observation = el.observation ? el.observation.value.trim() : "";
      return (
        "Physics Lab experiment - Newton's Second Law\n" +
        "mass = " + state.massKg.toFixed(1) + " kg\n" +
        "net force = " + state.forceN.toFixed(1) + " N\n" +
        "acceleration = " + a.toFixed(2) + " m/s^2 (a = F / m, idealized model)\n" +
        "What I observed: " + (observation || "(add your observation above)")
      );
    }

    function refreshTutorLink() {
      if (!el.tutorLink || !config.tutorBase) return;
      el.tutorLink.setAttribute(
        "href",
        config.tutorBase + "?prefill=" + encodeURIComponent(buildContext())
      );
    }

    // -- wiring --------------------------------------------------

    function onMassInput() {
      setMass(el.inputMass.value);
    }
    function onForceInput() {
      setForce(el.inputForce.value);
    }

    if (el.inputMass) {
      el.inputMass.addEventListener("input", onMassInput);
      el.inputMass.addEventListener("change", onMassInput);
    }
    if (el.inputForce) {
      el.inputForce.addEventListener("input", onForceInput);
      el.inputForce.addEventListener("change", onForceInput);
    }
    if (el.start) el.start.addEventListener("click", start);
    if (el.pause) el.pause.addEventListener("click", pause);
    if (el.reset) el.reset.addEventListener("click", reset);
    if (el.predictionSubmit) el.predictionSubmit.addEventListener("click", submitPrediction);
    if (el.predictionTest) el.predictionTest.addEventListener("click", testPrediction);
    if (el.observation) el.observation.addEventListener("input", refreshTutorLink);

    if (loop.reduced && el.motionNote) el.motionNote.hidden = false;

    loadStoredPrediction();
    syncInputs();
    setStatus("Ready. Set the mass and force, then press Start.");
    render();

    return {
      setMass: setMass,
      setForce: setForce,
      start: start,
      pause: pause,
      reset: reset,
      getState: getState
    };
  }

  PhysicsLab.NewtonsSecondLaw = {
    MIN_MASS_KG: MIN_MASS_KG,
    MAX_MASS_KG: MAX_MASS_KG,
    MIN_FORCE_N: MIN_FORCE_N,
    MAX_FORCE_N: MAX_FORCE_N,
    clampMass: clampMass,
    clampForce: clampForce,
    computeAcceleration: computeAcceleration
  };

  PhysicsLab.register("newtons_second_law", createNewtonsSecondLawSim);
})(window, document);
